begin;
create temporary table identity_checks(label text);
grant select,insert on identity_checks to anon,authenticated,service_role;
create function pg_temp.ok_identity(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAILED: %',label;end if;insert into identity_checks values(label);end $$;
create function pg_temp.reject_identity(command text,expected text,label text) returns void language plpgsql as $$declare code text;begin begin execute command;exception when others then get stacked diagnostics code=returned_sqlstate;end;perform pg_temp.ok_identity(code=expected,label);end $$;
insert into auth.users(id,email,raw_user_meta_data,email_confirmed_at) values
 ('74000000-0000-4000-8000-000000000001','identity-v@example.invalid','{"role":"vendor","name":"Identity vendor"}',now()),
 ('74000000-0000-4000-8000-000000000002','identity-c@example.invalid','{"role":"customer","name":"Identity customer"}',now()),
 ('74000000-0000-4000-8000-000000000003','identity-c2@example.invalid','{"role":"customer","name":"Identity customer 2"}',now());
select pg_temp.ok_identity((select count(*)=1 from public.vendors where id='74000000-0000-4000-8000-000000000001'),'vendor signup has vendor profile');
select pg_temp.ok_identity(not exists(select 1 from public.customers where id='74000000-0000-4000-8000-000000000001'),'vendor signup has no customer profile');
select pg_temp.reject_identity($q$insert into public.customers(id,name,email) values('74000000-0000-4000-8000-000000000001','Mixed','mixed@example.invalid')$q$,'42501','cannot create opposite profile');
select pg_temp.reject_identity($q$update public.users set role='customer' where id='74000000-0000-4000-8000-000000000001'$q$,'42501','account type immutable even through trusted SQL');
update public.vendors set phone='+919999990001' where id='74000000-0000-4000-8000-000000000001';
update public.customers set phone='+919999990001' where id='74000000-0000-4000-8000-000000000002';
select pg_temp.ok_identity(not exists(select 1 from eventra_security.account_phone_identities where user_id::text like '74000000-%'),'contact phone not automatically verified');
set local role service_role;
select public.bind_verified_app_phone('74000000-0000-4000-8000-000000000001','vendor','+919999990001','test-fixture','proof-v');
select public.bind_verified_app_phone('74000000-0000-4000-8000-000000000002','customer','+919999990001','test-fixture','proof-c');
select pg_temp.ok_identity(public.resolve_verified_app_phone('vendor','+919999990001')='74000000-0000-4000-8000-000000000001','same phone resolves vendor UID');
select pg_temp.ok_identity(public.resolve_verified_app_phone('customer','+919999990001')='74000000-0000-4000-8000-000000000002','same phone resolves different customer UID');
select pg_temp.reject_identity($q$select public.bind_verified_app_phone('74000000-0000-4000-8000-000000000003','customer','+919999990001','test-fixture','duplicate-proof')$q$,'23505','same-role number cannot be stolen');
select pg_temp.reject_identity($q$select public.bind_verified_app_phone('74000000-0000-4000-8000-000000000001','customer','+919999990002','test-fixture','bad-role')$q$,'42501','service binder validates actual account role');
select pg_temp.reject_identity($q$select public.bind_verified_app_phone('74000000-0000-4000-8000-000000000001','vendor','9999990001','test-fixture','bad-format')$q$,'22023','mapping requires canonical phone');
reset role;
set local role anon;
select set_config('request.jwt.claims','{}',true);
select pg_temp.reject_identity($q$select public.resolve_verified_app_phone('vendor','+919999990001')$q$,'42501','guest cannot enumerate phone mappings');
select pg_temp.reject_identity($q$select public.get_my_app_account('customer')$q$,'42501','guest cannot load identity');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"74000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.ok_identity(public.get_my_app_account('customer')->>'verified_phone'='+919999990001','customer can read own verified number');
select pg_temp.reject_identity($q$select public.get_my_app_account('vendor')$q$,'42501','customer cannot enter vendor app');
select pg_temp.reject_identity($q$select public.resolve_verified_app_phone('vendor','+919999990001')$q$,'42501','signed-in app cannot enumerate other identities');
select pg_temp.reject_identity($q$select public.bind_verified_app_phone('74000000-0000-4000-8000-000000000002','customer','+919999990002','fake','fake')$q$,'42501','client cannot self-verify phone');
select pg_temp.reject_identity($q$select public.remove_verified_app_phone('74000000-0000-4000-8000-000000000001','vendor')$q$,'42501','client cannot remove other mapping');
select pg_temp.reject_identity($q$select * from eventra_security.account_phone_identities$q$,'42501','private mappings unavailable by direct select');
select pg_temp.ok_identity(not exists(select 1 from public.vendors where id='74000000-0000-4000-8000-000000000001'),'same-number customer has no vendor private-profile access');
update public.customers set phone='+919999990009' where id='74000000-0000-4000-8000-000000000002';
select pg_temp.ok_identity(public.get_my_app_account('customer')->>'verified_phone'='+919999990001','editing contact number does not change login identity');
reset role;
update auth.users set raw_user_meta_data='{"role":"vendor"}' where id='74000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"74000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.ok_identity(public.get_my_account_role()='customer','editable metadata cannot switch role');
reset role;
update auth.users set banned_until=now()+interval '1 day' where id='74000000-0000-4000-8000-000000000001';
set local role service_role;
select pg_temp.ok_identity(public.resolve_verified_app_phone('vendor','+919999990001') is null,'banned vendor cannot resolve');
select pg_temp.ok_identity(public.resolve_verified_app_phone('customer','+919999990001')='74000000-0000-4000-8000-000000000002','vendor suspension does not suspend separate customer');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"74000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.reject_identity($q$select public.get_my_app_account('vendor')$q$,'42501','banned vendor cannot validate app identity');
select pg_temp.ok_identity(public.get_my_account_role() is null,'legacy role check also rejects suspension');
reset role;
set local role service_role;
select public.remove_verified_app_phone('74000000-0000-4000-8000-000000000002','customer');
select pg_temp.ok_identity(public.resolve_verified_app_phone('customer','+919999990001') is null,'trusted removal revokes mapping');
reset role;
select pg_temp.ok_identity((select relrowsecurity from pg_class where oid='eventra_security.account_phone_identities'::regclass),'mapping RLS enabled');
select pg_temp.ok_identity(not exists(select 1 from pg_publication_tables where schemaname='eventra_security' and tablename='account_phone_identities'),'phone map not published to realtime');
select count(*) as passed_account_identity_checks from identity_checks;
rollback;
